function parse(v,f){try{return v?JSON.parse(v):f}catch{return f}}function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}function tags(v){return String(v||'').split(',').map(x=>x.trim()).filter(Boolean)}function badge(v,tone){return'<span class="badge '+(tone||'')+'">'+esc(v)+'</span>'}function emptyRow(n){return'<tr><td colspan="'+n+'"><div class="empty">'+t('noItems')+'</div></td></tr>'}
async function api(url,options){const r=await fetch(url,options),data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||'Request failed');return data}let toastTimer;function notify(m,error){const el=$('#toast');el.textContent=m;el.className='toast'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='toast hidden',3500)}
async function busy(button,job){if(button.classList.contains('loading'))return;button.classList.add('loading');button.disabled=true;button.setAttribute('aria-busy','true');try{return await job()}catch(e){notify(e.message,true)}finally{button.classList.remove('loading');button.disabled=false;button.removeAttribute('aria-busy')}}
