function sliceList(key,items,q,match,filter){const cfg=listState[key],query=(q||'').toLowerCase().trim(),found=items.filter(item=>(!query||match(item).toLowerCase().includes(query))&&filter(item));const pages=Math.max(1,Math.ceil(found.length/cfg.size));cfg.page=Math.min(cfg.page,pages);return{items:found.slice((cfg.page-1)*cfg.size,cfg.page*cfg.size),pages,total:found.length}}
