function endSlot(i){const p=slots[i].split(':').map(Number),m=p[0]*60+p[1]+30;return String(Math.floor(m/60)%24).padStart(2,'0')+':'+String(m%60).padStart(2,'0')}function dayIntervals(d){const ids=Array.from(selected[d]).sort((a,b)=>a-b);if(!ids.length)return[];const out=[];let s=ids[0],p=s;for(const c of ids.slice(1)){if(c===p+1){p=c;continue}out.push({start:slots[s],end:endSlot(p)});s=c;p=c}out.push({start:slots[s],end:endSlot(p)});return out}
