function timeControl(selector,initial){const host=$(selector),values={h:0,m:0};host.innerHTML='<div class="time-picker"><button class="wheel-arrow" data-time-step="-5">−</button><div class="wheel-list" data-unit="h">'+Array.from({length:24},(_,i)=>'<div class="wheel-item">'+String(i).padStart(2,'0')+'</div>').join('')+'</div><b class="wheel-separator">:</b><div class="wheel-list" data-unit="m">'+Array.from({length:12},(_,i)=>'<div class="wheel-item">'+String(i*5).padStart(2,'0')+'</div>').join('')+'</div><button class="wheel-arrow" data-time-step="5">＋</button></div>';const cols=$$('.wheel-list',host);function paint(col,index){$$('.wheel-item',col).forEach((x,i)=>x.classList.toggle('selected',i===index))}function set(v,smooth){const p=v.split(':').map(Number);values.h=p[0]||0;values.m=Math.round((p[1]||0)/5)*5%60;cols[0].scrollTo({top:values.h*34,behavior:smooth?'smooth':'auto'});cols[1].scrollTo({top:(values.m/5)*34,behavior:smooth?'smooth':'auto'});paint(cols[0],values.h);paint(cols[1],values.m/5);updateReminderSummary()}cols.forEach((c,i)=>{let timer;c.onscroll=()=>{clearTimeout(timer);timer=setTimeout(()=>{const max=i?11:23,idx=Math.max(0,Math.min(max,Math.round(c.scrollTop/34)));if(i)values.m=idx*5;else values.h=idx;paint(c,idx);updateReminderSummary()},70)}});$$('[data-time-step]',host).forEach(b=>b.onclick=()=>{let total=values.h*60+values.m+Number(b.dataset.timeStep);if(total<0)total+=1440;if(total>=1440)total-=1440;set(String(Math.floor(total/60)).padStart(2,'0')+':'+String(total%60).padStart(2,'0'),true)});set(initial,false);return{get:()=>String(values.h).padStart(2,'0')+':'+String(values.m).padStart(2,'0'),set}}
const startWheel=timeControl('#remStartWheel','14:00'),stopWheel=timeControl('#remStopWheel','18:00');
