function editReminder(id){const x=state.reminders.find(v=>v.id===id);if(!x)return;const s=parse(x.schedule_json,{}),kind=s.kind==='weekly'?'recurring':(s.kind||'recurring');state.editingReminder=id;$('#remEditorTitle').textContent=t('editReminder');$('input[name="remType"][value="'+kind+'"]').checked=true;$('#remName').value=x.name;$('#remDescription').value=x.description||'';$('#remPriority').value=x.priority;$('#remTemplate').value=x.template_id;$('#remWork').value=x.work_schedule_id||'';$('#remDate').value=s.date||new Date().toISOString().slice(0,10);$('#remTimezone').value=s.timezone||'Asia/Qyzylorda';$('#remAllDay').checked=!!s.allDay;startWheel.set(s.startTime||'14:00');stopWheel.set(s.stopTime||'18:00');setRepeat(s.repeatEveryMinutes||30);renderDayChecks();setDays(s.weekdays||days.slice(0,5));selectedTargets=new Set(String(x.target_ids_csv||'').split(',').filter(Boolean));$('#remChecklist').checked=!!x.checklist_mode;$('#remEnabled').checked=!!x.enabled;pauseRules=parse(x.pause_rules_json,[]);renderPauseRules();const saved=parse(x.condition_rule_json,null);$('#remUseRule').checked=!!saved;if(saved){ruleState.root=saved.condition;ruleState.then=saved.then||[];ruleState.else=saved.else||[];drawConditions()}renderRecipients();updateReminderType();showView('reminders');scrollTo({top:0,behavior:'smooth'})}
$('#newReminder').onclick=resetReminder;$('#cancelReminder').onclick=resetReminder;$('#createMessageInline').onclick=()=>{resetTemplate();showView('messages')};$('#createWorkInline').onclick=()=>{resetWork();showView('work')};bindBusy('#saveReminder',async()=>{const kind=reminderType(),weekdays=kind==='ongoing'?days:(kind==='recurring'?$$('#remDays input:checked').map(i=>i.value):[]),body={name:$('#remName').value,description:$('#remDescription').value,template_id:$('#remTemplate').value,work_schedule_id:$('#remWork').value||null,priority:$('#remPriority').value,schedule:{kind,weekdays,date:kind==='once'?$('#remDate').value:undefined,startTime:startWheel.get(),stopTime:stopWheel.get(),allDay:$('#remAllDay').checked,repeatEveryMinutes:kind==='once'?10:getRepeat(),timezone:$('#remTimezone').value},pauseRules,checklistMode:$('#remChecklist').checked,targetIds:Array.from(selectedTargets),conditionRule:$('#remUseRule').checked?currentRule():null,enabled:$('#remEnabled').checked},url=state.editingReminder?'/api/reminders/'+state.editingReminder:'/api/reminders';await api(url,{method:state.editingReminder?'PUT':'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});notify(state.editingReminder?t('updated'):t('created'));resetReminder();await refreshAll()});

async function refreshRuns(){state.runs=await api('/api/runs');renderRuns();renderDashboard(await api('/api/dashboard'))}function renderRuns(){const f=$('#runFilter').value,r=sliceList('runs',state.runs,$('#runSearch').value,x=>x.reminder_name+' '+x.period_key,x=>f==='all'||x.status===f),h=$('#runCards');h.innerHTML=r.items.length?r.items.map(x=>'<div class="card run-card"><div class="run-top"><div><h2 class="card-title">'+esc(x.reminder_name)+'</h2><div class="run-meta">'+statusBadge(x.status)+badge(x.period_key,'')+badge(t('attempt')+' '+x.attempt,'')+(x.pause_until?badge(t('pause')+' '+t('until')+' '+new Date(x.pause_until).toLocaleString(),'warn'):'')+'</div></div><div class="actions"><button class="btn small" data-checklist="'+x.id+'">'+t('checklist')+'</button><input type="datetime-local" data-pause-time="'+x.id+'" style="width:185px"><button class="btn small" data-pause-run="'+x.id+'">'+t('pause')+'</button><button class="btn small" data-resume-run="'+x.id+'">'+t('resume')+'</button><button class="btn small danger" data-delete-run="'+x.id+'">'+t('delete')+'</button></div></div><div class="checklist hidden" id="checklist-'+x.id+'"></div></div>').join(''):'<div class="card empty">'+t('noItems')+'</div>';pager('#runPager','runs',r.pages,renderRuns);$$('[data-checklist]').forEach(b=>b.onclick=()=>busy(b,()=>loadChecklist(b.dataset.checklist)));$$('[data-pause-run]').forEach(b=>b.onclick=()=>busy(b,async()=>{const input=$('[data-pause-time="'+b.dataset.pauseRun+'"]'),d=input.value?new Date(input.value):new Date(Date.now()+3600000);await api('/api/runs/'+b.dataset.pauseRun+'/pause',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({until:d.toISOString()})});await refreshRuns()}));$$('[data-resume-run]').forEach(b=>b.onclick=()=>busy(b,async()=>{await api('/api/runs/'+b.dataset.resumeRun+'/resume',{method:'POST'});await refreshRuns()}));$$('[data-delete-run]').forEach(b=>b.onclick=()=>deleteEntity(b,state.runs.find(x=>x.id===b.dataset.deleteRun).reminder_name,'/api/runs/'+b.dataset.deleteRun,refreshRuns))}
async function loadChecklist(id){const items=await api('/api/runs/'+id+'/checklist'),h=$('#checklist-'+id);h.classList.remove('hidden');h.innerHTML=items.length?items.map(x=>'<div class="check-item"><div><strong>'+esc(x.label)+'</strong><div class="muted">'+esc(x.status)+'</div></div><button class="btn small" data-toggle-item="'+x.id+'">'+(x.status==='done'?t('markPending'):t('markDone'))+'</button></div>').join(''):'<div class="empty">'+t('noItems')+'</div>';$$('[data-toggle-item]',h).forEach(b=>b.onclick=()=>busy(b,async()=>{await api('/api/checklist/'+b.dataset.toggleItem+'/toggle',{method:'POST'});await refreshRuns()}))}bindBusy('#refreshRuns',refreshRuns);
async function refreshDeliveries(){state.deliveries=await api('/api/deliveries');renderDeliveries()}function renderDeliveries(){const f=$('#deliveryFilter').value,r=sliceList('deliveries',state.deliveries,$('#deliverySearch').value,x=>(x.reminder_name||'')+' '+(x.display_name||'')+' '+x.rendered_message,x=>f==='all'||x.status===f);$('#deliveryRows').innerHTML=r.items.length?r.items.map(x=>'<tr><td>'+esc(new Date(x.created_at+'Z').toLocaleString())+'</td><td>'+esc(x.reminder_name||'—')+'</td><td>'+esc(x.display_name||x.telegram_chat_id)+'</td><td>'+statusBadge(x.status)+'</td><td title="'+esc(x.error||'')+'">'+esc(String(x.rendered_message||'').slice(0,100))+'</td><td><button class="btn small danger" data-delete-delivery="'+x.id+'">'+t('delete')+'</button></td></tr>').join(''):emptyRow(6);pager('#deliveryPager','deliveries',r.pages,renderDeliveries);$$('[data-delete-delivery]').forEach(b=>b.onclick=()=>deleteEntity(b,t('deliveries'),'/api/deliveries/'+b.dataset.deleteDelivery,refreshDeliveries))}bindBusy('#refreshDeliveries',refreshDeliveries);

function currentSources(){return baseSources.concat(state.aliases.map(a=>'alias.'+a.key))}function removeNode(g,n){const i=g.children.indexOf(n);if(i>=0){g.children.splice(i,1);return true}return g.children.some(c=>c.type==='group'&&removeNode(c,n))}function drawConditions(){const h=$('#conditionTree');h.innerHTML='';drawGroup(ruleState.root,h,true);drawActions('then');drawActions('else');previewCondition()}function drawGroup(g,h,root){const box=document.createElement('div');box.className='rule-group';const head=document.createElement('div');head.className='rule-head';head.innerHTML='<strong>'+(root?'WHEN':'GROUP')+'</strong><select><option value="and">ALL / AND</option><option value="or">ANY / OR</option></select>'+(root?'':'<button class="btn small danger">'+t('delete')+'</button>');const s=$('select',head);s.value=g.operator;s.onchange=()=>{g.operator=s.value;previewCondition()};if(!root)$('button',head).onclick=async()=>{if(await askDelete(t('group'))){removeNode(ruleState.root,g);drawConditions()}};box.appendChild(head);g.children.forEach(n=>n.type==='group'?drawGroup(n,box,false):drawLeaf(n,box));const a=document.createElement('div');a.className='actions';const c=document.createElement('button');c.className='btn small';c.textContent='＋ '+t('condition');c.onclick=()=>{g.children.push({type:'condition',left:'schedule.isWorkingTime',operator:'eq',right:true});drawConditions()};const ng=document.createElement('button');ng.className='btn small';ng.textContent='＋ '+t('group');ng.onclick=()=>{g.children.push({type:'group',operator:'or',children:[]});drawConditions()};a.append(c,ng);box.append(a);h.append(box)}function drawLeaf(n,h){const r=document.createElement('div');r.className='rule-line',s=document.createElement('select'),o=document.createElement('select'),v=document.createElement('input'),d=document.createElement('button');currentSources().forEach(x=>s.add(new Option(x,x)));operators.forEach(x=>o.add(new Option(x,x)));s.value=n.left;o.value=n.operator;v.value=Array.isArray(n.right)?n.right.join(','):String(n.right==null?'':n.right);s.onchange=()=>{n.left=s.value;previewCondition()};o.onchange=()=>{n.operator=o.value;previewCondition()};v.oninput=()=>{const raw=v.value;n.right=['in','not_in','between'].includes(n.operator)?raw.split(',').map(x=>x.trim()):raw==='true'?true:raw==='false'?false:(raw!==''&&!isNaN(Number(raw))?Number(raw):raw);previewCondition()};d.className='btn icon danger';d.textContent='×';d.onclick=async()=>{if(await askDelete(t('condition'))){removeNode(ruleState.root,n);drawConditions()}};r.append(s,o,v,d);h.append(r)}
function actionValue(a){return a.type==='pause_run'?a.config?.minutes||'':a.type==='change_priority'?a.config?.priority||'':a.type==='mark_done'?a.config?.checklistItemId||'':a.type==='webhook'?a.config?.url||'':''}function setAction(a,v){if(a.type==='pause_run')a.config={minutes:Number(v||60)};else if(a.type==='change_priority')a.config={priority:v};else if(a.type==='mark_done')a.config={checklistItemId:v};else if(a.type==='webhook')a.config={url:v};else delete a.config}function drawActions(branch){const arr=ruleState[branch],h=$('#'+branch+'Actions');h.innerHTML=arr.length?arr.map((a,i)=>'<div class="list-row action-row"><select data-action-type="'+branch+'-'+i+'">'+actionTypes.map(x=>'<option '+(x===a.type?'selected':'')+'>'+x+'</option>').join('')+'</select><input data-action-config="'+branch+'-'+i+'" value="'+esc(actionValue(a))+'" '+(['send_message','select_pending','skip','stop_run'].includes(a.type)?'disabled':'')+'><button class="btn icon danger" data-remove-action="'+branch+'-'+i+'">×</button></div>').join(''):'<div class="empty">'+t('noItems')+'</div>';$$('[data-action-type]',h).forEach(x=>x.onchange=()=>{const p=x.dataset.actionType.split('-'),a=ruleState[p[0]][+p[1]];a.type=x.value;delete a.config;drawActions(p[0]);previewCondition()});$$('[data-action-config]',h).forEach(x=>x.oninput=()=>{const p=x.dataset.actionConfig.split('-');setAction(ruleState[p[0]][+p[1]],x.value);previewCondition()});$$('[data-remove-action]',h).forEach(b=>b.onclick=async()=>{if(await askDelete(t('action'))){const p=b.dataset.removeAction.split('-');ruleState[p[0]].splice(+p[1],1);drawActions(p[0]);previewCondition()}})}function human(n,d){d=d||0;return n.type==='condition'?'  '.repeat(d)+'• '+n.left+' '+n.operator+' '+JSON.stringify(n.right):'  '.repeat(d)+(n.operator==='and'?'ALL':'ANY')+'\n'+n.children.map(c=>human(c,d+1)).join('\n')}function currentRule(){return{condition:ruleState.root,then:ruleState.then,else:ruleState.else}}function previewCondition(){$('#conditionReadable').textContent=human(ruleState.root)+'\n\nTHEN\n'+ruleState.then.map(a=>'  • '+a.type).join('\n')+'\n\nELSE\n'+ruleState.else.map(a=>'  • '+a.type).join('\n');$('#conditionJson').textContent=JSON.stringify(currentRule(),null,2)}
$('#addRootCondition').onclick=()=>{ruleState.root.children.push({type:'condition',left:'schedule.currentTime',operator:'gte',right:'15:00'});drawConditions()};$('#addRootGroup').onclick=()=>{ruleState.root.children.push({type:'group',operator:'or',children:[]});drawConditions()};$$('[data-add-action]').forEach(b=>b.onclick=()=>{ruleState[b.dataset.addAction].push({type:b.dataset.addAction==='then'?'send_message':'skip'});drawActions(b.dataset.addAction);previewCondition()});$$('[data-condition-tab]').forEach(b=>b.onclick=()=>{$$('[data-condition-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#conditionReadable').classList.toggle('hidden',b.dataset.conditionTab!=='readable');$('#conditionJson').classList.toggle('hidden',b.dataset.conditionTab!=='json')});bindBusy('#validateCondition',async()=>{const r=await api('/api/rules/validate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(currentRule())});$('#conditionValidity').textContent=r.valid?t('validRule'):r.errors.join(', ');notify(r.valid?t('validRule'):t('invalidRule'),!r.valid)});

function renderCommands(){const h=$('#commandRows');h.innerHTML=commands.length?commands.map((c,i)=>'<div class="list-row"><input data-command-name="'+i+'" value="'+esc(c.command||'')+'"><input data-command-description="'+i+'" value="'+esc(c.description||'')+'"><button class="btn icon danger" data-remove-command="'+i+'">×</button></div>').join(''):'<div class="empty">'+t('noCommands')+'</div>';$$('[data-command-name]',h).forEach(x=>x.oninput=()=>commands[+x.dataset.commandName].command=x.value.replace(/^\//,''));$$('[data-command-description]',h).forEach(x=>x.oninput=()=>commands[+x.dataset.commandDescription].description=x.value);$$('[data-remove-command]',h).forEach(b=>b.onclick=async()=>{if(await askDelete(commands[+b.dataset.removeCommand].command)){commands.splice(+b.dataset.removeCommand,1);renderCommands()}})}function renderBot(){const b=state.bot;if(!b)return;$('#botName').value=b.name||'Cue';$('#botUsername').value=b.username||'';$('#botParse').value=b.default_parse_mode||'HTML';$('#botTimezone').value=b.timezone||'Asia/Qyzylorda';$('#botEnabled').checked=!!b.is_enabled;commands=parse(b.commands_json,[]);renderCommands()}$('#addCommand').onclick=()=>{commands.push({command:'start',description:lang==='ru'?'Запустить бота':'Start the bot'});renderCommands()};bindBusy('#saveBotConfig',async()=>{await api('/api/bot-config',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({name:$('#botName').value,username:$('#botUsername').value,default_parse_mode:$('#botParse').value,timezone:$('#botTimezone').value,commands,is_enabled:$('#botEnabled').checked})});notify(t('saved'));await refreshAll()});bindBusy('#syncCommands',async()=>{await api('/api/bot-config/sync-commands',{method:'POST'});notify(t('saved'))});
function renderAll(){if(!state.bot)return;renderClients();renderAliases();renderTemplateList();renderWorkRows();renderReminders();renderRuns();renderDeliveries();renderReadiness();renderBot();drawConditions();renderMessagePreview();renderWeek();renderExceptions();renderPauseRules();renderRecipients();updateReminderSummary()}
async function refreshAll(){const r=await Promise.all([api('/api/dashboard'),api('/api/clients'),api('/api/templates'),api('/api/work-schedules'),api('/api/reminders'),api('/api/aliases'),api('/api/runs'),api('/api/runtime/status'),api('/api/bot-config'),api('/api/deliveries')]);state.clients=r[1];state.templates=r[2];state.works=r[3];state.reminders=r[4];state.aliases=r[5];state.runs=r[6];state.runtime=r[7];state.bot=r[8];state.deliveries=r[9];fillSelect($('#remTemplate'),state.templates,t('selectMessage'));fillSelect($('#remWork'),state.works,t('defaultFallback'));renderDashboard(r[0]);renderAll()}
